#!/usr/bin/env Rscript
# ---------------------------------------------------------------------------
# update_data_dictionary.R
#
# DO NOT EDIT data/data_dictionary.csv BY HAND.
# This file is always generated from data_dictionary.md by this script.
#
# Usage: Rscript scripts/update_data_dictionary.R
# ---------------------------------------------------------------------------

suppressPackageStartupMessages({
  import::from("readr", read_lines, write_csv, write_lines, read_delim)
  import::from("dplyr", bind_rows, filter, mutate, arrange, across, everything, if_any)
  import::from("stringr", str_detect, str_match, str_trim)
  import::from("fs", file_exists)
  import::from("here", here)
})

md_path  <- here("data_dictionary.md")
csv_path <- here("data", "data_dictionary.csv")

if (!file_exists(md_path)) {
  stop("ERROR: data_dictionary.md not found in project root.")
}

# ---- helper : extract each markdown table ----
parse_md_tables <- function(lines) {
  out <- list()
  current_file <- NULL
  buf <- character()

  for (ln in lines) {
    # Detect section header of the form "## n filename.csv"
    if (str_detect(ln, "^##\\s+[0-9]+\\s+")) {
      if (length(buf) > 0 && !is.null(current_file)) {
        out[[current_file]] <- paste(buf, collapse = "\n")
        buf <- character()
      }
      current_file <- str_match(ln, "##\\s+[0-9]+\\s+(\\S+\\.csv)")[,2]
      next
    }
    if (str_detect(ln, "^\\|")) buf <- c(buf, ln)
  }
  if (length(buf) > 0 && !is.null(current_file))
    out[[current_file]] <- paste(buf, collapse = "\n")
  out
}

md_lines  <- read_lines(md_path)
tbl_texts <- parse_md_tables(md_lines)

dict_df <- bind_rows(lapply(names(tbl_texts), function(file) {
  df <- read_delim(tbl_texts[[file]],
    delim = "|",
    trim_ws = TRUE,
    skip = 1,
    comment = "",
    show_col_types = FALSE
  )
  # Remove columns with invalid names
  bad_cols <- which(names(df) == "" | grepl("^\\.\\.\\.", names(df)))
  if (length(bad_cols)) df <- df[ , -bad_cols, drop = FALSE]
  colnames(df) <- c("Column","Type","Units_or_levels","Description")
  df <- mutate(df, file = file, .before = 1)
  # Check columns for completeness
  stopifnot(all(c("Column","Type","Units_or_levels","Description") %in% names(df)))
  df
}))

# ---- normalise & filter ----
dict_df <- dict_df |>
  mutate(across(everything(), ~str_trim(.x))) |>
  filter(!if_any(everything(), ~ .x == "…")) |>
  arrange(file, Column)

# ---- write CSV with header ----
csv_header <- "# This file is autogenerated from data_dictionary.md; DO NOT EDIT BY HAND."
write_lines(csv_header, csv_path)
write_csv(dict_df, csv_path, na = "", append = TRUE)

invisible(csv_path)
